import { DESKTOP_COLS_NUMBER, MOBILE_COLS_NUMBER, TABLET_COLS_NUMBER } from "./constants";
// eslint-disable-next-line complexity
export const adjustGridState = (gridState) => {
    if (gridState.lg !== undefined && (gridState.lg < 1 || gridState.lg > DESKTOP_COLS_NUMBER)) {
        gridState.lg = gridState.lg > DESKTOP_COLS_NUMBER ? DESKTOP_COLS_NUMBER : gridState.lg < 1 ? undefined : gridState.lg;
    }
    if (gridState.md !== undefined && (gridState.md < 1 || gridState.md > TABLET_COLS_NUMBER)) {
        gridState.md = gridState.md > TABLET_COLS_NUMBER ? TABLET_COLS_NUMBER : gridState.md < 1 ? undefined : gridState.md;
    }
    if (gridState.sm !== undefined && (gridState.sm < 1 || gridState.sm > MOBILE_COLS_NUMBER)) {
        gridState.sm = gridState.sm > MOBILE_COLS_NUMBER ? MOBILE_COLS_NUMBER : gridState.sm < 1 ? undefined : gridState.sm;
    }
    if (gridState.lgStart !== undefined && (gridState.lgStart < 1 || gridState.lgStart > DESKTOP_COLS_NUMBER)) {
        gridState.lgStart = gridState.lgStart > DESKTOP_COLS_NUMBER ? DESKTOP_COLS_NUMBER : gridState.lgStart < 1 ? undefined : gridState.lgStart;
    }
    if (gridState.mdStart !== undefined && (gridState.mdStart < 1 || gridState.mdStart > TABLET_COLS_NUMBER)) {
        gridState.mdStart = gridState.mdStart > TABLET_COLS_NUMBER ? TABLET_COLS_NUMBER : gridState.mdStart < 1 ? undefined : gridState.mdStart;
    }
    if (gridState.smStart !== undefined && (gridState.smStart < 1 || gridState.smStart > MOBILE_COLS_NUMBER)) {
        gridState.smStart = gridState.smStart > MOBILE_COLS_NUMBER ? MOBILE_COLS_NUMBER : gridState.smStart < 1 ? undefined : gridState.smStart;
    }
};
